package com.petlis.service.impl;
import com.petlis.common.exception.BusinessException;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.annotation.Import;import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc
@SpringBootTest @Import(LegacyBankJdbcTestConfiguration.class)
@Transactional("legacyBankTestTransactions") @EnabledIfEnvironmentVariable(named="PETLIS_LOCAL_DB_TEST",matches="true")
class LegacyHospitalDraftItemsLocalDatabaseTest {
 @Autowired FeatureStore store;
 @Autowired com.fasterxml.jackson.databind.ObjectMapper json;
 @Autowired org.springframework.transaction.PlatformTransactionManager transactions;
 @Autowired org.springframework.test.web.servlet.MockMvc mvc;
 @Autowired SessionService sessions;LegacyHospitalHistoryLocalDatabaseTest f;LegacyHospitalDraftItemsService service;
 @BeforeEach void setup(){f=new LegacyHospitalHistoryLocalDatabaseTest();f.store=store;f.setup();f.gate("{\"enabled\":true,\"writeEnabled\":true,\"draftEnabled\":true,\"draftWriteEnabled\":true,\"draftItemsEnabled\":true}");store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET SampleStatus=-2 WHERE ListDiagnosisProjectId=?",f.f.order);store.jdbc().update("UPDATE lin_lb_infotesttype SET type=1 WHERE InfoTestTypeId=?",f.f.test);store.insert("INSERT INTO lin_lb_infotesttype_price(InfoTestTypeid,price,IsActive) VALUES(?,125.50,0)",f.f.test);store.insert("INSERT INTO lin_lb_infotesttype_price(InfoTestTypeid,price,IsActive) VALUES(?,200.00,1)",f.f.test);service=new LegacyHospitalDraftItemsService(store,f.f.access,f.service,new LegacyHospitalDraftService(store,f.f.access,f.service));}
 LegacyHospitalDraftItemsService.Command command(int test){return new LegacyHospitalDraftItemsService.Command((int)f.f.hospital,test,(String)service.selected(f.f.order,(int)f.f.hospital).get("editToken"),"items_"+UUID.randomUUID().toString().replace("-",""));}
 @Test void addUsesOriginalFirstPriceAndModelDefaultsWithoutChangingParent(){
  var before=store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",f.f.order);long count=store.jdbc().queryForObject("SELECT COUNT(*) FROM lin_lb_diagnosisdetail",Long.class);var c=command(f.f.test);long id=service.add(f.f.order,c);var d=store.one("SELECT * FROM lin_lb_diagnosisdetail WHERE DiagnosisDetailId=?",id);assertEquals(f.f.order+"-"+(count+1),d.get("GenterNO"));assertEquals(0,new BigDecimal("125.50").compareTo(new BigDecimal(d.get("TestPrice").toString())));assertEquals(d.get("TestPrice"),d.get("OrginalPrice"));assertEquals(0,new BigDecimal("10").compareTo(new BigDecimal(d.get("OrginalDiscount").toString())));for(String key:List.of("IsSendMail","IsCheckPass","PayStatus2","DiagnosisStatus","InfoTestTypeModelId"))assertEquals(0,((Number)d.get(key)).intValue());assertEquals("",d.get("PDFHttpUrl"));var info=store.one("SELECT MailReport,ReportResult FROM lin_lb_diagnosisdetail_info WHERE diagnosisdetail_id=?",id);assertEquals("",info.get("MailReport"));assertEquals("",info.get("ReportResult"));assertEquals(before,store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",f.f.order));assertEquals(id,service.add(f.f.order,c));assertEquals(409,assertThrows(BusinessException.class,()->service.add(f.f.order,command(f.f.test))).getCode());
 }
 @Test void removeDeletesOnlyOriginalDetailAndLeavesBodyCopyAsSourceDoes(){long id=service.add(f.f.order,command(f.f.test));store.jdbc().update("UPDATE lin_lb_diagnosisdetail_info SET ReportResult='owned saved body' WHERE diagnosisdetail_id=?",id);var body=store.one("SELECT * FROM lin_lb_diagnosisdetail_info WHERE diagnosisdetail_id=?",id);var c=command(f.f.test);service.remove(f.f.order,c);service.remove(f.f.order,c);assertEquals(0,store.jdbc().queryForObject("SELECT COUNT(*) FROM lin_lb_diagnosisdetail WHERE DiagnosisDetailId=?",Integer.class,id));assertEquals(body,store.one("SELECT * FROM lin_lb_diagnosisdetail_info WHERE diagnosisdetail_id=?",id));assertEquals(0,((List<?>)service.selected(f.f.order,(int)f.f.hospital).get("items")).size());}
 @Test void selectionCatalogPreservesSourceTypeActiveAndSelectedMarker(){var q=service.catalog(f.f.order,(int)f.f.hospital,f.f.prefix,1,0,10);assertEquals(1,((Number)q.get("total")).intValue());service.add(f.f.order,command(f.f.test));assertTrue(store.encode(service.catalog(f.f.order,(int)f.f.hospital,f.f.prefix,1,0,10)).contains("\"selected\":true"));assertEquals(0,((Number)service.catalog(f.f.order,(int)f.f.hospital,f.f.prefix,2,0,10).get("total")).intValue());store.jdbc().update("UPDATE lin_lb_infotesttype SET IsActive=0 WHERE InfoTestTypeId=?",f.f.test);assertEquals(0,((Number)service.catalog(f.f.order,(int)f.f.hospital,f.f.prefix,null,0,10).get("total")).intValue());assertEquals(1,((List<?>)service.selected(f.f.order,(int)f.f.hospital).get("items")).size());}
 @Test void changedDetailsWriteGateAndHospitalScopeAreRejected(){var stale=command(f.f.test);service.add(f.f.order,command(f.f.test));assertEquals(409,assertThrows(BusinessException.class,()->service.remove(f.f.order,stale)).getCode());assertEquals(403,assertThrows(BusinessException.class,()->service.selected(f.f.order,2147483647)).getCode());f.gate("{\"enabled\":true,\"writeEnabled\":true,\"draftEnabled\":true,\"draftWriteEnabled\":true,\"draftItemsEnabled\":\"true\"}");assertEquals(409,assertThrows(BusinessException.class,()->service.remove(f.f.order,command(f.f.test))).getCode());}

 @Test void auditFailureRollsBackAddAndRemoveAndSameRequestsRecover(){
  var faulty=new FeatureStore(store.jdbc(),json){@Override public long insert(String sql,Object...args){if(sql.startsWith("INSERT INTO lin_audit_record"))throw new BusinessException(409,"owned item audit failure");return super.insert(sql,args);}};
  var broken=new LegacyHospitalDraftItemsService(faulty,f.f.access,f.service,new LegacyHospitalDraftService(store,f.f.access,f.service));
  var tx=new org.springframework.transaction.support.TransactionTemplate(transactions);tx.setPropagationBehavior(org.springframework.transaction.TransactionDefinition.PROPAGATION_NESTED);var manager=(org.springframework.transaction.support.AbstractPlatformTransactionManager)transactions;boolean previous=manager.isNestedTransactionAllowed();manager.setNestedTransactionAllowed(true);
  try{var add=command(f.f.test);assertThrows(BusinessException.class,()->tx.execute(status->broken.add(f.f.order,add)));assertEquals(0,store.jdbc().queryForObject("SELECT COUNT(*) FROM lin_lb_diagnosisdetail WHERE ListDiagnosisProjectId=?",Integer.class,f.f.order));long id=service.add(f.f.order,add);var before=store.one("SELECT * FROM lin_lb_diagnosisdetail WHERE DiagnosisDetailId=?",id);var remove=command(f.f.test);assertThrows(BusinessException.class,()->tx.execute(status->broken.remove(f.f.order,remove)));assertEquals(before,store.one("SELECT * FROM lin_lb_diagnosisdetail WHERE DiagnosisDetailId=?",id));service.remove(f.f.order,remove);}finally{manager.setNestedTransactionAllowed(previous);}
 }
 @Test void realSessionCanAddReadRemoveAndReplayThroughScopedHttp()throws Exception{
  store.jdbc().update("UPDATE lin_lb_infohospital SET IsActive=1,CityId=1 WHERE InfoHospitalId=?",f.f.hospital);store.jdbc().update("UPDATE lin_user SET hospital_id=? WHERE id=?",f.f.hospital,f.f.actor);String token=sessions.issue(f.f.actor).getToken(),path="/api/orders/hospital-history/drafts/"+f.f.order+"/items";
  mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(path).contextPath("/api").param("hospitalId",String.valueOf(f.f.hospital))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isUnauthorized());
  mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(path).contextPath("/api").param("hospitalId","2147483647").header("Authorization","Bearer "+token)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.code").value(403));
  var add=command(f.f.test);for(int i=0;i<2;i++)mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(path+"/add").contextPath("/api").header("Authorization","Bearer "+token).contentType("application/json").content(json.writeValueAsString(add))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.code").value(200));
  mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(path).contextPath("/api").param("hospitalId",String.valueOf(f.f.hospital)).header("Authorization","Bearer "+token)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.data.items.length()").value(1));
  var remove=command(f.f.test);for(int i=0;i<2;i++)mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(path+"/remove").contextPath("/api").header("Authorization","Bearer "+token).contentType("application/json").content(json.writeValueAsString(remove))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.code").value(200));assertEquals(0,((List<?>)service.selected(f.f.order,(int)f.f.hospital).get("items")).size());
 }
}
